import React, { useEffect, useState } from 'react'; // Import useEffect
import { useParams } from 'react-router-dom'; // Import useParams for dynamic category
import axios from 'axios';
import '../styles/home-page.css';
import image1 from '../images/image1.jpg';

const HomePage = () => {
  const { categorySlug } = useParams(); // Get the category from the URL parameter
  const [expenses, setExpenses] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchExpensesCategories = async () => {
    try {
      const result = await axios.post('http://localhost:5001/api/finances/return-each-category-with-expenses');
      setCategories(result.data);
      setLoading(false);
    } catch (error) {
      setError(error.message);
      setLoading(false);
    }
  };

  const fetchExpensesFromCategory = async (categorySlug) => {
    try {
      const result = await axios.post('http://localhost:5001/api/finances/return-expenses-from-category', { category: categorySlug });
      setExpenses(result.data);
      setLoading(false);
    } catch (error) {
      setError(error.message);
      setLoading(false);
    }
  };

  useEffect(() => {
    if (categorySlug) {
      fetchExpensesFromCategory(categorySlug); // Fetch expenses for the selected category
    } else {
      fetchExpensesCategories(); // Fetch all categories if no categorySlug
    }
  }, [categorySlug]); // Run whenever categorySlug changes

  return (
    <div className="main-content">
      <div className="home-container">
        <div className="left-content">
          <h1 className="welcome-title">Welcome Kerim</h1>
          <p className="welcome-text">
            Welcome to your Smart Personal Finance Manager. Here you can manage your finances easily and effectively.
          </p>
        </div>
        <div className="image-container">
          <img src={image1} alt="Finance Image" />
        </div>
      </div>

      {/* Expenses Section */}
      <div className="expenses-container">
        <h2 className="expenses-title">Monthly Expenses 💵💸💰</h2>

        {/* Display Loading or Error */}
        {loading && <p>Loading...</p>}
        {error && <p>Error: {error}</p>}

        {/* Display Expenses by Category */}
        {categorySlug ? (
          <div className="category-expenses">
            {expenses.map((expense) => (
              <div className="expense-item" key={expense.date}>
                <span className="expense-name">{expense.expenseName}</span>
                <span className="expense-amount">{expense.expenseValue}KM</span>
                <span className="expense-date">{expense.date}</span>
              </div>
            ))}
          </div>
        ) : (
          <div className="expenses-list">
            {categories.map((categoryData) => {
              const { category, total } = categoryData;
              const categorySlug = category.toLowerCase().replace(/\s+/g, '-'); // Create URL-friendly slug
              return (
                <div className="expense-item" key={category}>
                  <span className="expense-name">{category}:</span>
                  <span className="expense-amount">{total}KM</span>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default HomePage;
